    if (line.isEmpty() || line.startsWith("#")) continue;
    if (line.startsWith("[") && line.endsWith("]")) section = line.substring(1, line.length() - 1).trim();
    else { int eq = line.indexOf('='); if (eq >= 0) result.put((section.isEmpty() ? "" : section + ".") + line.substring(0, eq).trim(), line.substring(eq + 1).trim()); }
}
