    for (int j = 1; j <= n; j++) {
        if (s.charAt(i-1) == t.charAt(j-1)) {
            dp[i][j] = dp[i-1][j-1];
        } else {
            int rc = sameClass(s.charAt(i-1), t.charAt(j-1)) ? 1 : 3;
            dp[i][j] = Math.min(dp[i-1][j-1] + rc, Math.min(dp[i-1][j] + 1, dp[i][j-1] + 1));
        }
    }
}
return dp[m][n];

